function enrollPairedTablet(input = {}, request = null) {
  const license = publicLicenseStatus();
  if (!license.active) return { ok: false, statusCode: 402, message: license.message || 'Windows 主机尚未激活。', license };
  const tabletId = String(input.tabletId || '').trim().slice(0, 120);
  const tabletCode = String(input.tabletMachineCode || '').trim().toUpperCase();
  if (!tabletId || tabletCode !== machineCode('tablet', tabletId)) {
    return { ok: false, statusCode: 400, message: '学生终端身份或固定机器码校验失败。' };
  }
  const students = readStudentsIndex();
  if (license.studentLimit && students.length > Number(license.studentLimit)) {
    return { ok: false, statusCode: 403, message: `当前学生数 ${students.length} 已超过授权上限（${license.studentLimit} 位）。`, license };
  }
  const devices = readDevices();
  const conflicting = machineCodeConflict(devices, 'tablet', tabletId, tabletCode);
  if (conflicting) return { ok: false, statusCode: 409, message: '固定机器码与另一设备身份冲突，已拒绝连接。' };
  const existing = devices.find((item) => String(item.id) === tabletId);
  if (existing?.revoked) {
    return { ok: false, statusCode: 403, message: '该设备已被撤销，不能自行恢复；请在主机端手动恢复后重试。' };
  }
  const activeDevices = devices.filter((item) => !item.revoked && String(item.id) !== tabletId);
  if (license.deviceLimit && activeDevices.length >= Number(license.deviceLimit)) {
    return { ok: false, statusCode: 403, message: `授权设备数已达上限（${license.deviceLimit} 台）。`, license };
  }
  const token = createDeviceToken();
  const now = new Date().toISOString();
  const requestedCapabilities = Array.isArray(input.tabletCapabilities) ? input.tabletCapabilities.map(String) : [];
  const deviceRole = normalizeTerminalDeviceRole(input.deviceRole, requestedCapabilities);
  const device = {
    ...(existing || {}),
    id: tabletId,
    name: String(input.tabletName || existing?.name || (deviceRole === 'teacher' ? 'Android 教师终端' : (input.tabletPlatform === 'windows' ? 'Windows 学生终端' : 'Android 平板'))).trim().slice(0, 80) || (deviceRole === 'teacher' ? '教师终端' : '学生终端'),
    machineCode: tabletCode,
    platform: String(input.tabletPlatform || existing?.platform || 'android').toLowerCase() === 'windows' ? 'windows' : 'android',
    deviceRole,
    tokenHash: hashDeviceToken(token),
    tokenPreview: `${token.slice(0, 7)}...${token.slice(-6)}`,
    terminalMode: normalizeTerminalMode(existing?.terminalMode, 'shared'),
    boundStudentId: String(existing?.boundStudentId || ''),
    capabilities: Array.from(new Set([
      ...(Array.isArray(existing?.capabilities) ? existing.capabilities : []),
      ...requestedCapabilities,
      ...(deviceRole === 'teacher' ? ['teacher-terminal-v1'] : ['student-session-v1']),
    ])),
    allowedStudentIds: normalizeTerminalMode(existing?.terminalMode, 'shared') === 'personal' && existing?.boundStudentId ? [String(existing.boundStudentId)] : [],
    allowedAllStudents: deviceRole === 'teacher' || normalizeTerminalMode(existing?.terminalMode, 'shared') === 'shared',
    autoAuthorizeNewStudents: deviceRole === 'teacher' || normalizeTerminalMode(existing?.terminalMode, 'shared') === 'shared',
    revoked: false,
    createdAt: existing?.createdAt || now,
    enrolledAt: now,
    lastSeenAt: now,
    lastIp: request ? requestClientIp(request) : String(input.tabletAddress || existing?.lastIp || ''),
    lastUserAgent: request ? requestUserAgent(request) : String(existing?.lastUserAgent || ''),
    pairedProtocolVersion: PAIR_PROTOCOL_VERSION,
  };
  writeDevices([...devices.filter((item) => String(item.id) !== tabletId), device]);
  appendHostTimeline({ type: 'device_pair_v2_accepted', title: 'Device connection accepted', detail: device.name, deviceId: tabletId });
  return { ok: true, statusCode: 200, token, device, requiresApproval: false, message: deviceRole === 'teacher' ? '教师终端已连接，可查看本主机学生并上传资料。' : '设备已连接。请选择个人终端或共享终端使用方式。' };
}

function savePairRequest(record) {
  const requests = refreshPairRequests();
  const index = requests.findIndex((item) => String(item.requestId) === String(record.requestId));
  const next = index >= 0
    ? requests.map((item, itemIndex) => itemIndex === index ? record : item)
    : [record, ...requests];
  writePairRequests(next);
  notify('onNativeHostServiceChanged', getHostServiceStatus());
  return record;
}

function acceptHostPairRequest(requestId) {
  const requests = refreshPairRequests();
  const current = requests.find((item) => String(item.requestId) === String(requestId));
  if (!current || current.status !== 'pending_host_accept') return JSON.stringify({ ok: false, message: '未找到待主机接受的连接请求。' });
  const transition = nextPairRequestStatus(current, 'accept');
  if (!transition.ok) return JSON.stringify({ ok: false, message: transition.message });
  const enrolled = enrollPairedTablet({
    tabletId: current.tabletId,
    tabletMachineCode: current.tabletMachineCode,
    tabletName: current.tabletName,
    tabletPlatform: current.tabletPlatform,
    tabletCapabilities: current.tabletCapabilities,
    tabletAddress: current.tabletAddress,
  });
  if (!enrolled.ok) return JSON.stringify(enrolled);
  savePairRequest({
    ...transition.request,
    issuedToken: enrolled.token,
    issuedTokenExpiresAt: new Date(Date.now() + 2 * 60 * 1000).toISOString(),
    deviceId: enrolled.device.id,
  });
  return JSON.stringify({ ok: true, message: enrolled.message, request: publicPairRequest(transition.request), device: publicDevice(enrolled.device), status: JSON.parse(getHostServiceStatus()) });
}

function rejectPairRequest(requestId) {
  const requests = refreshPairRequests();
  const current = requests.find((item) => String(item.requestId) === String(requestId));
  const transition = nextPairRequestStatus(current, 'reject');
  if (!transition.ok) return JSON.stringify({ ok: false, message: transition.message });
  savePairRequest(transition.request);
  appendHostTimeline({ type: 'device_pair_v2_rejected', title: 'Device connection rejected', detail: current?.tabletName || '', deviceId: current?.tabletId || '' });
  return JSON.stringify({ ok: true, message: '已拒绝连接请求。', request: publicPairRequest(transition.request), status: JSON.parse(getHostServiceStatus()) });
}

function inviteLanTablet(tabletId) {
  if (!hostDiscoverySocket) return JSON.stringify({ ok: false, message: '主机局域网发现服务未运行。' });
  const tablet = [...discoveredLanTablets.values()].find((item) => String(item.deviceId) === String(tabletId));
  if (!tablet) return JSON.stringify({ ok: false, message: '未找到该学生终端，请重新查找。' });
  const identity = getHostIdentity();
  const info = getConnectionInfo();
  const created = createPairRequest({
    initiator: 'host',
    hostId: identity.hostId,
    tabletId: tablet.deviceId,
    hostMachineCode: identity.machineCode,
    tabletMachineCode: tablet.machineCode,
    hostName: identity.displayName,
    tabletName: tablet.displayName,
    tabletPlatform: tablet.platform,
    tabletCapabilities: tablet.capabilities,
    hostAddress: info.serverUrl,
    tabletAddress: tablet.address,
  });
  savePairRequest(created.record);
  const payload = Buffer.from(JSON.stringify({
    type: 'AI_EDU_MANAGER_PAIR_INVITE',
    protocolVersion: PAIR_PROTOCOL_VERSION,
    requestId: created.record.requestId,
    requestToken: created.requestToken,
    targetTabletId: tablet.deviceId,
    targetTabletMachineCode: tablet.machineCode,
    hostId: identity.hostId,
    hostMachineCode: identity.machineCode,
    hostName: identity.displayName,
    appVersion: APP_VERSION,
    serverUrl: info.serverUrl,
    lanUrls: info.lanUrls,
    port: info.port,
    expiresAt: created.record.expiresAt,
  }), 'utf8');
  try {
    hostDiscoverySocket.send(payload, tablet.discoveryPort || HOST_DISCOVERY_PORT, tablet.address, (error) => {
      if (error) hostServiceLastError = `发送学生终端连接邀请失败：${error.message}`;
    });
    return JSON.stringify({ ok: true, message: '已发送连接邀请，请在学生终端点击接受。', request: publicPairRequest(created.record), status: JSON.parse(getHostServiceStatus()) });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `发送学生终端连接邀请失败：${error.message}` });
  }
}

async function handlePairRequestV2(request, response) {
  try {
    const body = await parseJsonBody(request);
    const identity = getHostIdentity();
    const tabletId = String(body.tabletId || '').trim().slice(0, 120);
    const tabletCode = String(body.tabletMachineCode || '').trim().toUpperCase();
    if (String(body.hostId || identity.hostId) !== identity.hostId || String(body.hostMachineCode || identity.machineCode) !== identity.machineCode) {
      sendJson(response, 409, { ok: false, message: '目标主机身份不一致，请重新查找主机。' });
      return;
    }
    if (!tabletId || tabletCode !== machineCode('tablet', tabletId) || !body.requestToken || !body.requestId) {
      sendJson(response, 400, { ok: false, message: '连接请求身份信息不完整。' });
      return;
    }
    const existing = readDevices().find((item) => String(item.id) === tabletId);
    if (existing?.revoked) {
      sendJson(response, 403, { ok: false, message: '该设备已被撤销，不能自行恢复。' });
      return;
    }
    const pairRequests = refreshPairRequests();
    const duplicate = pairRequests.find((item) => String(item.requestId) === String(body.requestId));
    if (duplicate) {
      if (!verifyRequestToken(duplicate, body.requestToken)) {
        sendJson(response, 409, { ok: false, message: '请求编号冲突。' });
        return;
      }
      sendJson(response, 200, { ok: true, request: publicPairRequest(duplicate), message: '连接请求已存在。' });
      return;
    }
    const supersededAt = new Date().toISOString();
    const withoutSuperseded = pairRequests.map((item) => {
      if (item.status !== 'pending_host_accept' || String(item.tabletId) !== tabletId) return item;
      return { ...item, status: 'cancelled', updatedAt: supersededAt, cancelledAt: supersededAt, cancelReason: 'superseded' };
    });
    if (JSON.stringify(withoutSuperseded) !== JSON.stringify(pairRequests)) writePairRequests(withoutSuperseded);
    const created = createPairRequest({
      initiator: 'tablet',
      requestId: String(body.requestId),
      requestToken: String(body.requestToken),
      hostId: identity.hostId,
      tabletId,
      hostMachineCode: identity.machineCode,
      tabletMachineCode: tabletCode,
      hostName: identity.displayName,
      tabletName: String(body.tabletName || (body.platform === 'windows' ? 'Windows 学生终端' : 'Android 学生终端')),
      tabletPlatform: String(body.platform || 'android'),
      tabletCapabilities: Array.isArray(body.capabilities) ? body.capabilities : [],
      hostAddress: getConnectionInfo().serverUrl,
      tabletAddress: requestClientIp(request),
    });
    savePairRequest(created.record);
    appendHostTimeline({ type: 'device_pair_v2_requested', title: 'Device connection requested', detail: created.record.tabletName, deviceId: tabletId });
    sendJson(response, 202, { ok: true, request: publicPairRequest(created.record), message: '已发送连接请求，请等待主机端接受。' });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `连接请求失败：${error.message}` });
  }
}

async function handlePairCancelV2(request, response) {
  try {
    const body = await parseJsonBody(request);
    const current = refreshPairRequests().find((item) => String(item.requestId) === String(body.requestId));
    if (!current || !verifyRequestToken(current, body.requestToken)) {
      sendJson(response, 403, { ok: false, message: '连接请求不存在或令牌无效。' });
      return;
    }
    const transition = nextPairRequestStatus(current, 'cancel');
    if (!transition.ok) {
      sendJson(response, 409, { ok: false, message: transition.message, request: publicPairRequest(transition.request) });
      return;
    }
    savePairRequest(transition.request);
    appendHostTimeline({ type: 'device_pair_v2_cancelled', title: 'Device connection request cancelled', detail: current.tabletName || current.requestId, deviceId: current.tabletId || '' });
    sendJson(response, 200, { ok: true, request: publicPairRequest(transition.request), message: '连接请求已取消。' });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `取消连接失败：${error.message}` });
  }
}

function handlePairStatusV2(request, response, url) {
  const requestId = String(url.searchParams.get('requestId') || '');
  const token = String(url.searchParams.get('requestToken') || '');
  const current = refreshPairRequests().find((item) => String(item.requestId) === requestId);
  if (!current || !verifyRequestToken(current, token)) {
    sendJson(response, 404, { ok: false, message: '连接请求不存在或令牌无效。' });
    return;
  }
  sendJson(response, 200, {
    ok: true,
    request: publicPairRequest(current),
    token: current.status === 'accepted' && Date.parse(current.issuedTokenExpiresAt || 0) > Date.now() ? current.issuedToken || '' : '',
    requiresApproval: current.status === 'accepted',
  });
}

async function handleTabletPairAcceptV2(request, response) {
  try {
    const body = await parseJsonBody(request);
    const requests = refreshPairRequests();
    const current = requests.find((item) => String(item.requestId) === String(body.requestId));
    if (!current || current.status !== 'pending_tablet_accept' || !verifyRequestToken(current, body.requestToken)) {
      sendJson(response, 403, { ok: false, message: '连接邀请无效、已过期或已处理。' });
      return;
    }
    if (String(body.tabletId || '') !== current.tabletId || String(body.tabletMachineCode || '').toUpperCase() !== current.tabletMachineCode.toUpperCase()) {
      sendJson(response, 409, { ok: false, message: '接受邀请的平板身份与目标设备不一致。' });
      return;
    }
    const enrolled = enrollPairedTablet({
      tabletId: current.tabletId,
      tabletMachineCode: current.tabletMachineCode,
      tabletName: body.tabletName || current.tabletName,
      tabletPlatform: current.tabletPlatform || body.platform,
      tabletCapabilities: current.tabletCapabilities || body.capabilities,
      tabletAddress: requestClientIp(request),
    }, request);
    if (!enrolled.ok) {
      sendJson(response, enrolled.statusCode || 400, enrolled);
      return;
    }
    const transition = nextPairRequestStatus(current, 'accept');
    savePairRequest({
      ...transition.request,
      issuedToken: enrolled.token,
      issuedTokenExpiresAt: new Date(Date.now() + 2 * 60 * 1000).toISOString(),
      deviceId: enrolled.device.id,
    });
    sendJson(response, 200, { ok: true, token: enrolled.token, requiresApproval: true, message: enrolled.message, device: publicDevice(enrolled.device) });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `接受连接邀请失败：${error.message}` });
  }
}

async function handlePairRejectV2(request, response) {
  try {
    const body = await parseJsonBody(request);
    const current = refreshPairRequests().find((item) => String(item.requestId) === String(body.requestId));
    if (!current || !verifyRequestToken(current, body.requestToken)) {
      sendJson(response, 403, { ok: false, message: '连接请求不存在或令牌无效。' });
      return;
    }
    const transition = nextPairRequestStatus(current, 'reject');
    if (!transition.ok) {
      sendJson(response, 409, { ok: false, message: transition.message });
      return;
    }
    savePairRequest(transition.request);
    sendJson(response, 200, { ok: true, request: publicPairRequest(transition.request), message: '已拒绝连接邀请。' });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `拒绝连接失败：${error.message}` });
  }
}

async function handlePairConfirm(request, response) {
  try {
    const body = await parseJsonBody(request);
    const pairCode = String(body.pairCode || '').trim();
    const session = getPairSession();
    if (!pairCode || pairCode !== session.pairCode || session.expiresAtMs <= Date.now()) {
      sendJson(response, 403, { ok: false, message: '配对码无效或已过期。' });
      return;
    }
    const license = publicLicenseStatus();
    if (!license.active) {
      sendJson(response, 402, { ok: false, message: license.message || 'Windows 主机尚未激活，请先在主机端输入授权码。', license });
      return;
    }
    const existingStudents = readStudentsIndex();
    const deviceId = String(body.deviceId || `device-${Date.now()}-${crypto.randomBytes(4).toString('hex')}`);
    const existingDevice = readDevices().find((item) => String(item.id) === deviceId);
    if (existingDevice?.revoked) {
      sendJson(response, 403, { ok: false, message: '该设备已被撤销，不能通过旧配对码自行恢复；请在主机端手动恢复。' });
      return;
    }
    const activeDevices = readDevices().filter((item) => !item.revoked && String(item.id) !== deviceId);
    if (license.deviceLimit && activeDevices.length >= Number(license.deviceLimit)) {
      sendJson(response, 403, { ok: false, message: `授权设备数已达上限（${license.deviceLimit} 台）。请在 Windows 主机端撤销旧设备或升级授权。`, license });
      return;
    }
    if (license.studentLimit && existingStudents.length > Number(license.studentLimit)) {
      sendJson(response, 403, { ok: false, message: `当前学生数 ${existingStudents.length} 已超过授权上限（${license.studentLimit} 位）。请升级授权或减少学生后再绑定。`, license });
      return;
    }
    const token = createDeviceToken();
    const requestedCapabilities = Array.isArray(body.capabilities) ? body.capabilities.map(String) : [];
    const deviceRole = normalizeTerminalDeviceRole(body.deviceRole, requestedCapabilities);
    const device = {
      id: deviceId,
      name: String(body.deviceName || body.name || (deviceRole === 'teacher' ? 'Android 教师终端' : '平板设备')).slice(0, 80),
      tokenHash: hashDeviceToken(token),
      tokenPreview: `${token.slice(0, 7)}...${token.slice(-6)}`,
      deviceRole,
      terminalMode: 'shared',
      boundStudentId: '',
      capabilities: Array.from(new Set([...requestedCapabilities, ...(deviceRole === 'teacher' ? ['teacher-terminal-v1'] : ['student-session-v1'])])),
      allowedStudentIds: [],
      allowedAllStudents: true,
      autoAuthorizeNewStudents: true,
      revoked: false,
      createdAt: new Date().toISOString(),
      lastSeenAt: new Date().toISOString(),
      lastIp: requestClientIp(request),
      lastUserAgent: requestUserAgent(request),
    };
    const devices = readDevices().filter((item) => item.id !== device.id);
    devices.push(device);
    writeDevices(devices);
    activePairSession = null;
    notify('onNativeHostServiceChanged', getHostServiceStatus());
    sendJson(response, 200, {
      ok: true,
      token,
      requiresApproval: false,
      message: deviceRole === 'teacher' ? '教师终端已登记，可直接读取本主机学生。' : '设备已登记，默认为共享终端；学生可扫码或输入个人 ID。',
      device: publicDevice(device),
      students: [],
    });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `Pair confirm failed: ${error.message}` });
  }
}

async function handleDeviceEnroll(request, response) {
  if (!requireAuth(request, response)) return;
  if (request.authContext?.type !== 'admin') {
    sendJson(response, 403, { ok: false, message: '只有主机连接信息可以登记新设备。' });
    return;
  }
  try {
    const body = await parseJsonBody(request);
    const license = publicLicenseStatus();
    const deviceId = String(body.deviceId || `device-${Date.now()}-${crypto.randomBytes(4).toString('hex')}`).slice(0, 120);
    const devices = readDevices();
    const activeDevices = devices.filter((item) => !item.revoked && String(item.id) !== deviceId);
    if (license.deviceLimit && activeDevices.length >= Number(license.deviceLimit)) {
      sendJson(response, 403, { ok: false, message: `授权设备数已达上限（${license.deviceLimit} 台）。请撤销旧设备或升级授权。` });
      return;
    }
    const token = createDeviceToken();
    const requestedCapabilities = Array.isArray(body.capabilities) ? body.capabilities.map(String) : [];
    const deviceRole = normalizeTerminalDeviceRole(body.deviceRole, requestedCapabilities);
    const device = {
      id: deviceId,
      name: String(body.deviceName || body.name || (deviceRole === 'teacher' ? 'Android 教师终端' : '平板设备')).trim().slice(0, 80) || (deviceRole === 'teacher' ? '教师终端' : '平板设备'),
      tokenHash: hashDeviceToken(token),
      tokenPreview: `${token.slice(0, 7)}...${token.slice(-6)}`,
      deviceRole,
      terminalMode: 'shared',
      boundStudentId: '',
      capabilities: Array.from(new Set([...requestedCapabilities, ...(deviceRole === 'teacher' ? ['teacher-terminal-v1'] : ['student-session-v1'])])),
      allowedStudentIds: [],
      allowedAllStudents: true,
      autoAuthorizeNewStudents: true,
      revoked: false,
      createdAt: devices.find((item) => String(item.id) === deviceId)?.createdAt || new Date().toISOString(),
      enrolledAt: new Date().toISOString(),
      lastSeenAt: new Date().toISOString(),
      lastIp: requestClientIp(request),
      lastUserAgent: requestUserAgent(request),
    };
    writeDevices([...devices.filter((item) => String(item.id) !== deviceId), device]);
    appendHostTimeline({ type: 'device_enrolled', title: 'Tablet awaiting authorization', detail: device.name, deviceId });
    notify('onNativeHostServiceChanged', getHostServiceStatus());
    sendJson(response, 200, {
      ok: true,
      token,
      requiresApproval: false,
      message: deviceRole === 'teacher' ? '教师终端已登记，可直接读取本主机学生。' : '设备已登记，默认为共享终端；学生可扫码或输入个人 ID。',
      device: publicDevice(device),
    });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `设备登记失败：${error.message}` });
  }
}

function handleDeviceHeartbeat(request, response) {
  if (!requireAuth(request, response)) return;
  const auth = request.authContext;
  const device = ['device', 'student_session'].includes(auth?.type)
    ? readDevices().find((item) => String(item.id) === String(auth.deviceId))
    : null;
  sendJson(response, 200, {
    ok: true,
    at: new Date().toISOString(),
    device: device ? publicDevice(device) : null,
    studentCount: readStudentsIndex().length,
  });
}

function directPackagePaths(manifestId) {
  const state = readCollaborationState();
  const safeId = String(manifestId || '');
  if (!/^[A-Za-z0-9._-]{1,160}$/.test(safeId)) throw new Error('协作包标识无效。');
  const root = path.join(collaborationRootPath(), '.direct-received', state.node.nodeId);
  return {
    state,
    writing: path.join(root, `.${safeId}.writing`),
    completed: path.join(root, safeId),
  };
}

function directPackageFilePath(locations, file) {
  const contentRoot = path.resolve(locations.writing, 'content');
  const targetPath = path.resolve(contentRoot, String(file?.relativePath || ''));
  if (!targetPath.startsWith(`${contentRoot}${path.sep}`)) throw new Error('协作文件路径越界。');
  return targetPath;
}

function directAvailableDiskBytes(targetPath) {
  try {
    if (typeof fs.statfsSync !== 'function') return Number.POSITIVE_INFINITY;
    let probe = path.resolve(targetPath);
    while (!fs.existsSync(probe) && path.dirname(probe) !== probe) probe = path.dirname(probe);
    const stats = fs.statfsSync(probe);
    return Number(stats.bavail || stats.bfree || 0) * Number(stats.bsize || 0);
  } catch {
    return Number.POSITIVE_INFINITY;
  }
}

function sha256FileDirect(filePath) {
  return new Promise((resolve, reject) => {
    const hash = crypto.createHash('sha256');
    const stream = fs.createReadStream(filePath);
    stream.on('error', reject);
    stream.on('data', (chunk) => hash.update(chunk));
    stream.on('end', () => resolve(hash.digest('hex')));
  });
}

function pruneDirectNonces(now = Date.now()) {
  for (const [key, expiresAt] of collaborationDirectNonces.entries()) {
    if (expiresAt <= now) collaborationDirectNonces.delete(key);
  }
}

function authenticateDirectRequest(request, pathname, actualContentSha256 = '') {
  const state = readCollaborationState();
  const bindingId = String(request.headers['x-edu-binding-id'] || '');
  const sourceNodeId = String(request.headers['x-edu-node-id'] || '');
  const binding = state.bindings.find((item) => item.bindingId === bindingId && item.status === 'active' && !item.revokedAt);
  const secret = binding ? collaborationDirectSecret(binding) : '';
  if (!binding || !secret || !binding.participantNodeIds?.includes(state.node.nodeId) || !binding.participantNodeIds?.includes(sourceNodeId)) {
    throw new Error('未找到有效的双主机协作认证。');
  }
  const verified = verifyDirectRequest({
    secret,
    method: request.method,
    pathname,
    headers: request.headers,
  });
  if (!verified.ok) throw new Error(verified.message);
  if (actualContentSha256 && verified.contentSha256 !== actualContentSha256) throw new Error('直传内容摘要不匹配。');
  pruneDirectNonces();
  const nonceKey = `${bindingId}:${verified.nonce}`;
  if (collaborationDirectNonces.has(nonceKey)) throw new Error('检测到重复的直传请求。');
  collaborationDirectNonces.set(nonceKey, Date.now() + 10 * 60 * 1000);
  return { state, binding, sourceNodeId, verified };
}

async function handleCollaborationDirectInit(request, response, pathname) {
  try {
    const bodyBuffer = await readRequestBuffer(request, 2 * 1024 * 1024);
    const auth = authenticateDirectRequest(request, pathname, sha256DirectContent(bodyBuffer));
    const payload = bodyBuffer.length ? JSON.parse(bodyBuffer.toString('utf8')) : {};
    const requestedProtocol = String(payload.protocolVersion || '1.0');
    if (Number(requestedProtocol.split('.')[0]) > Number(DIRECT_PROTOCOL_VERSION.split('.')[0])) {
      throw new Error(`直传协议版本不兼容：${requestedProtocol}。`);
    }
    const manifest = payload.manifest;
    if (manifest?.sourceNodeId !== auth.sourceNodeId || manifest?.targetNodeId !== auth.state.node.nodeId) {
      throw new Error('协作包发送方或目标主机不匹配。');
    }
    const files = Array.isArray(manifest?.files) ? manifest.files : [];
    if (!manifest?.manifestId || !files.length || files.length > 1000) throw new Error('协作包清单无效。');
    if (files.some((item) => !Number.isFinite(Number(item.size)) || Number(item.size) < 0 || Number(item.size) > MAX_UPLOAD_BYTES)) {
      throw new Error('协作包包含超出限制的文件。');
    }
    if (files.reduce((sum, item) => sum + Number(item.size || 0), 0) > 2 * 1024 * 1024 * 1024) {
      throw new Error('协作包总大小超出限制。');
    }
    const locations = directPackagePaths(manifest.manifestId);
    if (fs.existsSync(locations.completed)) {
      sendJson(response, 200, { ok: true, duplicate: true, manifestId: manifest.manifestId });
      return;
    }
    fs.mkdirSync(path.join(locations.writing, 'content'), { recursive: true });
    const importLedger = safeReadJson(collaborationImportLedgerPath(), { objects: {} });
    for (const file of files) {
      const known = importLedger.objects?.[file.objectId];
      if (!known?.importedPath || String(known.sha256 || '') !== String(file.sha256 || '') || !fs.existsSync(known.importedPath)) continue;
      const candidate = directPackageFilePath(locations, file);
      fs.mkdirSync(path.dirname(candidate), { recursive: true });
      if (!fs.existsSync(candidate)) fs.copyFileSync(known.importedPath, candidate);
    }
    const remainingBytes = files.reduce((sum, file) => {
      try {
        const candidate = directPackageFilePath(locations, file);
        const received = fs.existsSync(candidate) ? Math.min(fs.statSync(candidate).size, Number(file.size || 0)) : 0;
        return sum + Math.max(0, Number(file.size || 0) - received);
      } catch {
        return sum + Number(file.size || 0);
      }
    }, 0);
    const freeBytes = directAvailableDiskBytes(locations.writing);
    if (Number.isFinite(freeBytes) && freeBytes < remainingBytes + 64 * 1024 * 1024) {
      throw new Error('接收端磁盘空间不足，未开始传输。');
    }
    const existing = safeReadJson(path.join(locations.writing, 'manifest.json'), null);
    if (existing && JSON.stringify(existing) !== JSON.stringify(manifest)) throw new Error('同名协作包清单发生冲突。');
    writeJsonAtomic(path.join(locations.writing, 'manifest.json'), manifest);
    const fileProgress = [];
    for (let index = 0; index < files.length; index += 1) {
      const file = files[index];
      const candidate = directPackageFilePath(locations, file);
      let receivedBytes = fs.existsSync(candidate) ? fs.statSync(candidate).size : 0;
      if (receivedBytes > Number(file.size || 0)) {
        fs.rmSync(candidate, { force: true });
        receivedBytes = 0;
      } else if (Number(file.size || 0) === 0 && !fs.existsSync(candidate)) {
        fs.mkdirSync(path.dirname(candidate), { recursive: true });
        fs.writeFileSync(candidate, Buffer.alloc(0));
      } else if (receivedBytes === Number(file.size || 0) && receivedBytes > 0) {
        const digest = await sha256FileDirect(candidate);
        if (digest !== file.sha256) {
          fs.rmSync(candidate, { force: true });
          receivedBytes = 0;
        }
      }
      fileProgress.push({ index, receivedBytes, size: Number(file.size || 0), complete: receivedBytes === Number(file.size || 0) });
    }
    sendJson(response, 200, {
      ok: true,
      manifestId: manifest.manifestId,
      fileCount: files.length,
      protocolVersion: DIRECT_PROTOCOL_VERSION,
      supportsResume: true,
      maxChunkBytes: 8 * 1024 * 1024,
      files: fileProgress,
    });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `初始化协作直传失败：${error.message}` });
  }
}

async function handleCollaborationDirectChunk(request, response, pathname, manifestId, fileIndex, offsetValue) {
  try {
    const locations = directPackagePaths(manifestId);
    const manifest = safeReadJson(path.join(locations.writing, 'manifest.json'), null);
    const file = manifest?.files?.[Number(fileIndex)];
    if (!file) throw new Error('协作包文件序号无效。');
    const expectedBytes = Number(request.headers['content-length'] || 0);
    if (!Number.isFinite(expectedBytes) || expectedBytes <= 0 || expectedBytes > 8 * 1024 * 1024) throw new Error('协作文件分块大小无效。');
    const bodyBuffer = await readRequestBuffer(request, 8 * 1024 * 1024);
    if (bodyBuffer.length !== expectedBytes) throw new Error('协作文件分块不完整。');
    const actualChunkSha256 = sha256DirectContent(bodyBuffer);
    const auth = authenticateDirectRequest(request, pathname, actualChunkSha256);
    if (manifest.sourceNodeId !== auth.sourceNodeId || manifest.targetNodeId !== auth.state.node.nodeId) {
      throw new Error('协作包与当前绑定不匹配。');
    }
    if (String(request.headers['x-edu-file-sha256'] || '') !== String(file.sha256 || '')) throw new Error('协作文件总摘要声明不匹配。');
    const offset = Number(offsetValue);
    if (!Number.isSafeInteger(offset) || offset < 0 || offset + bodyBuffer.length > Number(file.size)) throw new Error('协作文件分块位置无效。');
    const targetPath = directPackageFilePath(locations, file);
    fs.mkdirSync(path.dirname(targetPath), { recursive: true });
    const currentSize = fs.existsSync(targetPath) ? fs.statSync(targetPath).size : 0;
    if (offset < currentSize) {
      if (offset + bodyBuffer.length > currentSize) throw new Error('协作文件分块与现有断点重叠。');
      const handle = fs.openSync(targetPath, 'r');
      let existing;
      try {
        existing = Buffer.allocUnsafe(bodyBuffer.length);
        fs.readSync(handle, existing, 0, existing.length, offset);
      } finally {
        fs.closeSync(handle);
      }
      if (!existing.equals(bodyBuffer)) throw new Error('重复分块内容与已接收数据不一致。');
      sendJson(response, 200, { ok: true, duplicate: true, manifestId, fileIndex: Number(fileIndex), receivedBytes: currentSize });
      return;
    }
    if (offset !== currentSize) {
      sendJson(response, 409, { ok: false, message: '分块前仍有缺失数据。', expectedOffset: currentSize });
      return;
    }
    fs.appendFileSync(targetPath, bodyBuffer);
    const receivedBytes = currentSize + bodyBuffer.length;
    if (receivedBytes === Number(file.size)) {
      const digest = await sha256FileDirect(targetPath);
      if (digest !== file.sha256) {
        fs.rmSync(targetPath, { force: true });
        throw new Error('协作文件 SHA-256 校验失败，已清除错误断点。');
      }
    }
    sendJson(response, 200, { ok: true, manifestId, fileIndex: Number(fileIndex), receivedBytes, complete: receivedBytes === Number(file.size) });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `接收协作文件分块失败：${error.message}` });
  }
}

async function handleCollaborationDirectFile(request, response, pathname, manifestId, fileIndex) {
  try {
    const locations = directPackagePaths(manifestId);
    const manifest = safeReadJson(path.join(locations.writing, 'manifest.json'), null);
    const file = manifest?.files?.[Number(fileIndex)];
    if (!file) throw new Error('协作包文件序号无效。');
    const auth = authenticateDirectRequest(request, pathname);
    if (manifest.sourceNodeId !== auth.sourceNodeId || manifest.targetNodeId !== auth.state.node.nodeId) {
      throw new Error('协作包与当前绑定不匹配。');
    }
    if (auth.verified.contentSha256 !== file.sha256) throw new Error('协作文件声明摘要不匹配。');
    const targetPath = directPackageFilePath(locations, file);
    const streamed = await streamRequestToFile(request, {
      targetPath,
      maxBytes: MAX_UPLOAD_BYTES,
      expectedBytes: Number(file.size),
      hashAlgorithm: 'sha256',
    });
    if (streamed.sha256 !== file.sha256) {
      fs.rmSync(targetPath, { force: true });
      throw new Error('协作文件 SHA-256 校验失败。');
    }
    sendJson(response, 200, { ok: true, manifestId, fileIndex: Number(fileIndex), size: streamed.size });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `接收协作文件失败：${error.message}` });
  }
}

async function handleCollaborationDirectCommit(request, response, pathname, manifestId) {
  try {
    const bodyBuffer = await readRequestBuffer(request, 1024 * 1024);
    const auth = authenticateDirectRequest(request, pathname, sha256DirectContent(bodyBuffer));
    const payload = bodyBuffer.length ? JSON.parse(bodyBuffer.toString('utf8')) : {};
    if (payload.manifestId !== manifestId) throw new Error('协作包提交标识不匹配。');
    const locations = directPackagePaths(manifestId);
    let packageRoot = locations.completed;
    if (!fs.existsSync(packageRoot)) {
      const manifest = safeReadJson(path.join(locations.writing, 'manifest.json'), null);
      if (!manifest || manifest.sourceNodeId !== auth.sourceNodeId || manifest.targetNodeId !== auth.state.node.nodeId) {
        throw new Error('协作包清单不存在或目标不匹配。');
      }
      for (const file of manifest.files || []) {
        const candidate = path.resolve(locations.writing, 'content', String(file.relativePath || ''));
        if (!fs.existsSync(candidate) || fs.statSync(candidate).size !== Number(file.size)) throw new Error(`协作文件尚未完整接收：${file.relativePath}`);
        if (await sha256FileDirect(candidate) !== file.sha256) throw new Error(`协作文件摘要校验失败：${file.relativePath}`);
      }
      fs.writeFileSync(path.join(locations.writing, 'READY'), manifestId, 'utf8');
      fs.mkdirSync(path.dirname(locations.completed), { recursive: true });
      fs.renameSync(locations.writing, locations.completed);
      packageRoot = locations.completed;
    }
    const manifest = safeReadJson(path.join(packageRoot, 'manifest.json'), null);
    const receipt = importCollaborationPackage(collaborationRootPath(), { packageRoot, manifest }, {
      targetNodeId: auth.state.node.nodeId,
      ledgerPath: collaborationImportLedgerPath(),
    });
    const taskImport = ingestImportedCollaborationTasks();
    const projectImport = ingestImportedProjectPublications();
    const studentArchiveImport = ingestImportedStudentArchives();
    appendHostTimeline({
      type: 'collaboration_direct_received',
      title: 'Collaboration package received',
      detail: `${manifestId}: ${receipt.status}; projects ${projectImport.importedPublications}, files ${projectImport.importedFiles}, student archive assets ${studentArchiveImport.imported}, known ${projectImport.duplicateFiles + studentArchiveImport.duplicates}`,
    });
    notify('onNativeHostServiceChanged', getHostServiceStatus());
    notify('onNativeCollaborationChanged', JSON.stringify({ manifestId, receipt, taskImport, projectImport, studentArchiveImport }));
    sendJson(response, 200, { ok: true, receipt, taskImport, projectImport, studentArchiveImport });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `提交协作直传失败：${error.message}` });
  }
}

function invokeIncomingTeamArchive(access, scoped) {
  const candidates = Array.from(new Set([
    ...(Array.isArray(scoped.searchQueries) ? scoped.searchQueries : []),
    scoped.query,
  ].map((item) => String(item || '').trim()).filter(Boolean))).slice(0, 6);
  if (!['search', 'context_bundle'].includes(scoped.queryType) || candidates.length <= 1) {
    return invokeLocalArchiveScopes(access, scoped, scoped.allowedScopes);
  }
  const resources = [];
  let baseResult = null;
  for (const candidate of candidates) {
    const result = invokeLocalArchiveScopes(access, { ...scoped, query: candidate }, scoped.allowedScopes);
    baseResult ||= result;
    resources.push(...(result.resources || []));
    if (resources.length >= scoped.limit * 2) break;
  }
  const deduped = Array.from(new Map(resources.map((resource) => [String(resource.uri || ''), resource])).values())
    .sort((left, right) => (
      Number(right.matchScore || 0) - Number(left.matchScore || 0)
      || String(right.modifiedAt || '').localeCompare(String(left.modifiedAt || ''))
    ))
    .slice(0, scoped.limit);
  return {
    ...(baseResult || { ok: true }),
    query: String(scoped.query || ''),
    resources: deduped,
    count: deduped.length,
  };
}

function annotateOutgoingTeamArchiveResult(result, sourceNodeId) {
  const catalog = teamKnowledgeCatalog();
  const resources = (result?.resources || []).map((resource) => annotateTeamKnowledgeResource(resource, catalog, {
    sourceNodeId,
    freshness: 'live',
  }));
  return { ...result, resources, count: resources.length };
}

async function handleRemoteArchiveQuery(request, response, pathname) {
  try {
    const bodyBuffer = await readRequestBuffer(request, 512 * 1024);
    const auth = authenticateDirectRequest(request, pathname, sha256DirectContent(bodyBuffer));
    const incoming = normalizeRemoteArchiveRequest(bodyBuffer.length ? JSON.parse(bodyBuffer.toString('utf8')) : {});
    if (incoming.bindingId && incoming.bindingId !== auth.binding.bindingId) throw new Error('远程知识请求与协作关系不匹配。');
    const scoped = resolveIncomingRemoteArchiveScope(incoming, auth);
    const rawResult = scoped.teamQuery
      ? invokeIncomingTeamArchive(currentArchiveAccess(), scoped)
      : invokeRelatedLocalArchive(currentArchiveAccess(), scoped);
    const result = scoped.teamQuery
      ? annotateOutgoingTeamArchiveResult(rawResult, auth.state.node.nodeId)
      : rawResult;
    const archiveResponse = normalizeRemoteArchiveResponse({
      sourceNodeId: auth.state.node.nodeId,
      requesterNodeId: auth.sourceNodeId,
      scope: { type: scoped.scopeType, id: incoming.scopeId, localId: scoped.localScopeId },
      queryType: scoped.queryType,
      freshness: 'live',
      result,
    }, incoming);
    appendHostTimeline({
      type: 'remote_archive_query',
      title: 'Remote archive query served',
      detail: `${auth.sourceNodeId}: ${scoped.scopeType}/${scoped.localScopeId} ${scoped.queryType}`,
    });
    sendJson(response, 200, { ok: true, schema: REMOTE_ARCHIVE_RESPONSE_SCHEMA, response: archiveResponse });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `远程知识查询失败：${error.message}` });
  }
}

function resolveIncomingAgentKnowledgeScope(incoming = {}) {
  if (String(incoming.scopeType || 'student') !== 'team') {
    return resolveAgentKnowledgeStudentScope(incoming, readStudentsIndex().map(toHostStudent));
  }
  return { ...incoming, scopeType: 'team', scopeId: 'team', scopeName: '本机团队' };
}

async function handleAgentKnowledgeQuery(request, response) {
  try {
    if (!requireAuth(request, response)) return;
    const bodyBuffer = await readRequestBuffer(request, 512 * 1024);
    const incoming = bodyBuffer.length ? JSON.parse(bodyBuffer.toString('utf8')) : {};
    const scopedIncoming = resolveIncomingAgentKnowledgeScope(incoming);
    const query = normalizeAgentKnowledgeQuestion(scopedIncoming);
    if (query.scopeType === 'team' && request.authContext?.type !== 'admin') {
      sendJson(response, 403, { ok: false, message: '学生终端不能使用团队知识查询范围。' });
      return;
    }
    if (query.scopeType === 'student' && !isStudentAllowed(request, query.scopeId)) {
      sendJson(response, 403, { ok: false, message: '当前调用方没有访问该学生知识的权限。' });
      return;
    }
    if (query.scopeType === 'project' && request.authContext?.type !== 'admin') {
      const project = readProjects().map(normalizeProject).find((item) => String(item.id) === String(query.scopeId));
      const studentIds = (project?.studentIds || []).map(String);
      if (!project || !studentIds.some((studentId) => isStudentAllowed(request, studentId))) {
        sendJson(response, 403, { ok: false, message: '当前调用方没有访问该项目知识的权限。' });
        return;
      }
    }
    const result = parseJsonObject(await queryAgentKnowledge(JSON.stringify(scopedIncoming)));
    sendJson(response, result.ok ? 200 : 202, result);
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `Agent 知识查询失败：${error.message}` });
  }
}

async function handleAgentConversationSubmission(request, response) {
  try {
    if (!requireAuth(request, response)) return;
    const bodyBuffer = await readRequestBuffer(request, 5 * 1024 * 1024);
    const incoming = bodyBuffer.length ? JSON.parse(bodyBuffer.toString('utf8')) : {};
    const submission = normalizeAgentConversationSubmission(incoming);
    if (submission.scopeType === 'student' && !isStudentAllowed(request, submission.scopeId)) {
      sendJson(response, 403, { ok: false, message: '当前调用方不能向该学生档案投递对话。' });
      return;
    }
    if (submission.scopeType === 'project') {
      const project = readProjects().map(normalizeProject).find((item) => String(item.id) === String(submission.scopeId));
      if (!project || !projectAllowed(request, project)) {
        sendJson(response, 403, { ok: false, message: '当前调用方不能向该学习项目投递对话。' });
        return;
      }
    }
    const result = parseJsonObject(submitAgentConversation(JSON.stringify(submission)));
    appendHostTimeline({
      type: result.ok ? 'agent_conversation_submitted' : 'agent_conversation_submission_failed',
      title: result.ok ? 'Agent conversation submitted' : 'Agent conversation submission failed',
      detail: result.ok
        ? `${submission.sourceAgent}: ${submission.scopeType || 'unassigned'}/${submission.scopeId || 'pending'}; ${submission.messages.length} message(s)`
        : String(result.message || 'submission failed').slice(0, 500),
      studentId: submission.scopeType === 'student' ? submission.scopeId : '',
      projectId: submission.scopeType === 'project' ? submission.scopeId : '',
    });
    sendJson(response, result.ok ? 200 : 400, result);
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `保存 Agent 对话失败：${error.message}` });
  }
}

function handleHostRequest(request, response) {
  if (request.method === 'OPTIONS') {
    sendJson(response, 200, { ok: true });
    return;
  }
  let url;
  try {
    url = new URL(request.url || '/', `http://${request.headers.host || 'localhost'}`);
  } catch {
    sendJson(response, 400, { ok: false, message: 'Bad Request' });
    return;
  }

  const pathname = decodeURIComponent(url.pathname);
  if (request.method === 'POST' && pathname === '/api/agent/knowledge/query') {
    handleAgentKnowledgeQuery(request, response);
    return;
  }
  if (request.method === 'POST' && pathname === '/api/agent/conversation/submit') {
    handleAgentConversationSubmission(request, response);
    return;
  }
  if (request.method === 'POST' && pathname === REMOTE_ARCHIVE_PATH) {
    handleRemoteArchiveQuery(request, response, pathname);
    return;
  }
  if (request.method === 'GET' && pathname === '/api/collaboration/direct/capabilities') {
    sendJson(response, 200, {
      ok: true,
      transportId: LAN_DIRECT_TRANSPORT_ID,
      protocolVersion: DIRECT_PROTOCOL_VERSION,
      supportsStreaming: true,
      supportsResume: true,
      maxChunkBytes: 8 * 1024 * 1024,
      maxFileBytes: MAX_UPLOAD_BYTES,
    });
    return;
  }
  if (request.method === 'POST' && pathname === '/api/collaboration/direct/packages') {
    handleCollaborationDirectInit(request, response, pathname);
    return;
  }
  const directFileMatch = pathname.match(/^\/api\/collaboration\/direct\/packages\/([^/]+)\/files\/(\d+)$/);
  if (request.method === 'PUT' && directFileMatch) {
    handleCollaborationDirectFile(request, response, pathname, directFileMatch[1], directFileMatch[2]);
    return;
  }
  const directChunkMatch = pathname.match(/^\/api\/collaboration\/direct\/packages\/([^/]+)\/files\/(\d+)\/chunks\/(\d+)$/);
  if (request.method === 'PUT' && directChunkMatch) {
    handleCollaborationDirectChunk(request, response, pathname, directChunkMatch[1], directChunkMatch[2], directChunkMatch[3]);
    return;
  }
  const directCommitMatch = pathname.match(/^\/api\/collaboration\/direct\/packages\/([^/]+)\/commit$/);
  if (request.method === 'POST' && directCommitMatch) {
    handleCollaborationDirectCommit(request, response, pathname, directCommitMatch[1]);
    return;
  }
  if (request.method === 'GET' && pathname === '/api/health') {
    handleHealth(request, response);
    return;
  }
  const courseAssetMatch = pathname.match(/^\/api\/course-assets\/([^/]+)$/);
  if (request.method === 'GET' && courseAssetMatch) {
    handleCourseAsset(response, courseAssetMatch[1]);
    return;
  }
  if (request.method === 'POST' && pathname === '/api/pair/confirm') {
    handlePairConfirm(request, response);
    return;
  }
  if (request.method === 'POST' && pathname === '/api/pair/request') {
    handlePairRequestV2(request, response);
    return;
  }
  if (request.method === 'GET' && pathname === '/api/pair/status') {
    handlePairStatusV2(request, response, url);
    return;
  }
  if (request.method === 'POST' && pathname === '/api/pair/tablet-accept') {
    handleTabletPairAcceptV2(request, response);
    return;
  }
  if (request.method === 'POST' && pathname === '/api/pair/reject') {
    handlePairRejectV2(request, response);
    return;
  }
  if (request.method === 'POST' && pathname === '/api/pair/cancel') {
    handlePairCancelV2(request, response);
    return;
  }
  if (request.method === 'POST' && pathname === '/api/device/enroll') {
    handleDeviceEnroll(request, response);
    return;
  }
  if (request.method === 'POST' && pathname === '/api/device/heartbeat') {
    handleDeviceHeartbeat(request, response);
    return;
  }
  if (pathname === '/api/device/mode' && ['GET', 'POST'].includes(request.method)) {
    handleDeviceMode(request, response);
    return;
  }
  if (request.method === 'POST' && pathname === '/api/student-session/login') {
    handleStudentSessionLogin(request, response);
    return;
  }
  if (request.method === 'POST' && pathname === '/api/student-session/auto') {
    handleStudentSessionAuto(request, response);
    return;
  }
  if (request.method === 'GET' && pathname === '/api/student-session/me') {
    handleStudentSessionMe(request, response);
    return;
  }
  if (request.method === 'POST' && pathname === '/api/student-session/logout') {
    handleStudentSessionLogout(request, response);
    return;
  }
  if (request.method === 'GET' && pathname === '/api/students') {
    handleStudents(request, response);
    return;
  }
  if (request.method === 'GET' && pathname === '/api/assets') {
    handleAssets(request, response);
    return;
  }
  if (request.method === 'GET' && pathname === '/api/projects') {
    handleProjects(request, response);
    return;
  }
  if (request.method === 'POST' && pathname === '/api/projects') {
    handleProjectCreate(request, response);
    return;
  }
  const projectMaterialMatch = pathname.match(/^\/api\/projects\/([^/]+)\/materials$/);
  if (request.method === 'POST' && projectMaterialMatch) {
    handleProjectMaterialUpload(request, response, projectMaterialMatch[1], url);
    return;
  }
  const projectArchiveFilesMatch = pathname.match(/^\/api\/projects\/([^/]+)\/archive\/files$/);
  if (request.method === 'GET' && projectArchiveFilesMatch) {
    handleProjectArchiveFiles(request, response, projectArchiveFilesMatch[1]);
    return;
  }
  const projectArchiveFileMatch = pathname.match(/^\/api\/projects\/([^/]+)\/archive\/file$/);
  if (request.method === 'GET' && projectArchiveFileMatch) {
    handleProjectArchiveFile(request, response, projectArchiveFileMatch[1], url);
    return;
  }
  const projectPromotionMatch = pathname.match(/^\/api\/projects\/([^/]+)\/promotion$/);
  if (request.method === 'POST' && projectPromotionMatch) {
    handleProjectPromotion(request, response, projectPromotionMatch[1]);
    return;
  }
  const projectPromotionPublishMatch = pathname.match(/^\/api\/projects\/([^/]+)\/promotion\/publish$/);
  if (request.method === 'POST' && projectPromotionPublishMatch) {
    handleProjectPromotionPublish(request, response, projectPromotionPublishMatch[1]);
    return;
  }
  const projectPromotionPlanMatch = pathname.match(/^\/api\/projects\/([^/]+)\/promotion\/plan$/);
  if (request.method === 'GET' && projectPromotionPlanMatch) {
    handleProjectPromotionPlan(request, response, projectPromotionPlanMatch[1]);
    return;
  }
  const projectPromotionExecuteMatch = pathname.match(/^\/api\/projects\/([^/]+)\/promotion\/execute$/);
  if (request.method === 'POST' && projectPromotionExecuteMatch) {
    handleProjectPromotionExecute(request, response, projectPromotionExecuteMatch[1]);
    return;
  }
  const materialMatch = pathname.match(/^\/api\/students\/([^/]+)\/materials$/);
  if (request.method === 'POST' && materialMatch) {
    handleMaterialUpload(request, response, materialMatch[1], url);
    return;
  }
  const studentCoursesMatch = pathname.match(/^\/api\/students\/([^/]+)\/courses$/);
  if (request.method === 'GET' && studentCoursesMatch) {
    handleStudentCourses(request, response, studentCoursesMatch[1]);
    return;
  }
  const reportsMatch = pathname.match(/^\/api\/students\/([^/]+)\/reports$/);
  if (request.method === 'GET' && reportsMatch) {
    handleLearningReports(request, response, reportsMatch[1]);
    return;
  }
  const reportFileMatch = pathname.match(/^\/api\/students\/([^/]+)\/reports\/([^/]+)$/);
  if (request.method === 'GET' && reportFileMatch) {
    handleLearningReportFile(request, response, reportFileMatch[1], reportFileMatch[2]);
    return;
  }
  const growthSummaryMatch = pathname.match(/^\/api\/students\/([^/]+)\/growth-summary$/);
  if (request.method === 'GET' && growthSummaryMatch) {
    handleStudentGrowthSummary(request, response, growthSummaryMatch[1]);
    return;
  }
  const archiveFilesMatch = pathname.match(/^\/api\/students\/([^/]+)\/archive\/files$/);
  if (request.method === 'GET' && archiveFilesMatch) {
    handleArchiveFiles(request, response, archiveFilesMatch[1]);
    return;
  }
  const archiveFileMatch = pathname.match(/^\/api\/students\/([^/]+)\/archive\/file$/);
  if (request.method === 'GET' && archiveFileMatch) {
    handleArchiveFile(request, response, archiveFileMatch[1], url);
    return;
  }
  const digestStatusMatch = pathname.match(/^\/api\/students\/([^/]+)\/digest-status$/);
  if (request.method === 'GET' && digestStatusMatch) {
    handleDigestStatus(request, response, digestStatusMatch[1]);
    return;
  }
  sendJson(response, 404, { ok: false, message: 'Not Found' });
}

function startHostService(options = {}) {
  const locked = licenseRequiredJson('主机服务');
  if (locked) {
    hostServiceLastError = JSON.parse(locked).message;
    return JSON.stringify({ ...JSON.parse(getHostServiceStatus()), ok: false, message: hostServiceLastError });
  }
  if (hostServer) return getHostServiceStatus();
  const settings = readSettings();
  if (!options.preserveUsageMode && normalizeHostUsageMode(settings.usageMode, 'host') !== 'host_terminal') {
    writeSettings({ ...settings, usageMode: 'host_terminal' });
  }
  ensureApiToken();
  const port = getHostServicePort();
  try {
    hostServer = http.createServer(handleHostRequest);
    hostServer.on('error', (error) => {
      hostServiceLastError = error.message;
      hostServer = null;
      stopHostDiscovery();
      notify('onNativeHostServiceChanged', getHostServiceStatus());
    });
    hostServer.listen(port, '0.0.0.0', () => {
      hostServiceStartedAt = new Date().toISOString();
      hostServiceLastError = '';
      startHostDiscovery();
      prepareAllAgentKnowledgeAccess();
      notify('onNativeHostServiceChanged', getHostServiceStatus());
    });
    return getHostServiceStatus();
  } catch (error) {
    hostServer = null;
    hostServiceLastError = error.message;
    return getHostServiceStatus();
  }
}

function stopHostService() {
  stopHostDiscovery();
  if (!hostServer) return getHostServiceStatus();
  const server = hostServer;
  hostServer = null;
  server.close(() => {
    notify('onNativeHostServiceChanged', getHostServiceStatus());
  });
  return getHostServiceStatus();
}

function repairHostService() {
  const messages = [];
  try {
    fs.mkdirSync(defaultStudentBaseDir(), { recursive: true });
    messages.push('学生资料根目录已确认。');
  } catch (error) {
    messages.push(`学生资料根目录不可写：${error.message}`);
  }
  ensureApiToken();
  messages.push('API Token 已确认。');
  if (hostServer) {
    const server = hostServer;
    hostServer = null;
    server.close(() => {
      startHostService();
      notify('onNativeHostServiceChanged', getHostServiceStatus());
    });
    return JSON.stringify({
      ok: true,
      message: `${messages.join(' ')} 主机服务正在重启，请稍后刷新状态。`,
      status: JSON.parse(getHostServiceStatus()),
    });
  }
  const status = JSON.parse(startHostService());
  return JSON.stringify({
    ok: Boolean(status.running),
    message: `${messages.join(' ')} ${status.running ? '主机服务已启动。' : '主机服务启动失败，请查看诊断结果。'}`,
    status,
  });
}

function getHostServiceStatus() {
  resetUploadCounterIfNeeded();
  const info = getConnectionInfo();
  const pairPayload = getPairPayload();
  const hostIdentity = getHostIdentity();
  const pairRequests = refreshPairRequests();
  const discoveredTablets = [...discoveredLanTablets.values()]
    .filter((item) => Date.now() - Date.parse(item.lastSeenAt || 0) <= 5 * 60 * 1000)
    .sort((a, b) => String(b.lastSeenAt).localeCompare(String(a.lastSeenAt)));
  return JSON.stringify({
    usageMode: getHostUsageMode(),
    running: Boolean(hostServer),
    discoveryRunning: Boolean(hostDiscoverySocket),
    discoveryPort: HOST_DISCOVERY_PORT,
    pairProtocolVersion: PAIR_PROTOCOL_VERSION,
    hostIdentity,
    pairRequests: pairRequests.map(publicPairRequest),
    pendingPairRequestCount: pairRequests.filter((item) => item.status === 'pending_host_accept').length,
    discoveredTablets,
    discoveredTerminals: discoveredTablets,
    lastTabletDiscoveryAt,
    port: info.port,
    serverUrl: info.serverUrl,
    lanUrls: info.lanUrls,
    tailscaleUrl: info.tailscaleUrl,
    tailscaleUrls: info.tailscaleUrls,
    connectionMode: info.connectionMode,
    apiToken: info.apiToken,
    pairCode: pairPayload.pairCode,
    pairExpiresAt: pairPayload.expiresAt,
    pairPayload,
    pairPayloadText: JSON.stringify(pairPayload),
    devices: readDevices().map(publicDevice),
    studentCount: readStudentsIndex().length,
    students: hostStudentStats(),
    todayUploadCount,
    recentUploads: readUploadRecords().slice(0, 8),
    license: publicLicenseStatus(),
    startedAt: hostServiceStartedAt,
    lastError: hostServiceLastError,
  });
}

function getHostServiceDiagnostics() {
  resetUploadCounterIfNeeded();
  const info = getConnectionInfo();
  const students = readStudentsIndex();
  const devices = readDevices();
  const activeDevices = devices.filter((device) => !device.revoked);
  const checks = [
    {
      label: '主机服务',
      ok: Boolean(hostServer),
      detail: hostServer ? `运行中，端口 ${info.port}` : '未启动。需要学生终端连接时，请先启动主机服务。',
      suggestion: hostServer ? '保持控制台打开即可。' : '在系统设置的“使用模式”中选择“主机-终端模式”，点击“启动服务”。',
    },
    {
      label: '局域网地址',
      ok: info.lanUrls.length > 0,
      detail: info.lanUrls.length > 0 ? info.lanUrls.join('；') : '没有检测到可用于平板访问的局域网地址。',
      suggestion: info.lanUrls.length > 0 ? '平板需连接同一 Wi-Fi，并使用二维码或扫码内容绑定。' : '检查电脑是否连接 Wi-Fi/网线，或稍后刷新服务状态。',
    },
    {
      label: '局域网设备发现',
      ok: Boolean(hostDiscoverySocket),
      detail: hostDiscoverySocket ? `UDP ${HOST_DISCOVERY_PORT} 正在监听，支持 V1/V2 双向发现。` : `UDP ${HOST_DISCOVERY_PORT} 未监听。`,
      suggestion: hostDiscoverySocket
        ? '若搜索不到设备，请确认两端同一 Wi-Fi、关闭访客网络/客户端隔离，并允许专用网络 UDP 广播。'
        : '启动或修复主机服务；防火墙应允许本应用使用 UDP 18778。',
    },
    {
      label: 'Tailscale 地址',
      ok: info.tailscaleUrls.length > 0,
      detail: info.tailscaleUrls.length > 0 ? info.tailscaleUrls.join('；') : '未检测到 Tailscale 100.x 地址。',
      suggestion: info.tailscaleUrls.length > 0 ? '平板和主机加入同一个 Tailscale 网络后，可作为局域网失败时的远程回退地址。' : '如需远程连接，请先安装并登录 Tailscale；仅局域网使用可忽略。',
    },
    {
      label: 'API Token',
      ok: Boolean(info.apiToken),
      detail: info.apiToken ? `已生成：${info.apiToken.slice(0, 8)}...${info.apiToken.slice(-6)}` : '未生成。',
      suggestion: info.apiToken ? '无需手动输入，平板扫码配对后会自动保存设备 token。' : '启动主机服务后会自动生成。',
    },
    {
      label: '学生索引',
      ok: students.length > 0,
      detail: students.length > 0 ? `${students.length} 位学生可供授权。` : '还没有同步学生，请先初始化或新建学生。',
      suggestion: students.length > 0 ? '可在设备列表中设置每台学生终端的使用模式和资料范围。' : '先在 Windows 控制台初始化或新建教育管家。',
    },
    {
      label: '学生终端设备',
      ok: activeDevices.length > 0,
      detail: activeDevices.length > 0 ? `${activeDevices.length} 台有效设备，${devices.length - activeDevices.length} 台已撤销。` : '暂无有效绑定设备。',
      suggestion: activeDevices.length > 0 ? '如资料串学生，请检查设备的学生访问范围。' : '学生终端可查找主机并请求连接，或开启“等待主机连接”由 Windows 邀请。',
    },
    {
      label: '最近错误',
      ok: !hostServiceLastError,
      detail: hostServiceLastError || '无。',
      suggestion: hostServiceLastError ? '若提示端口占用，请更换端口；若平板连不上，请检查防火墙和同一网络。' : '暂无需要处理的服务错误。',
    },
  ];
  return JSON.stringify({
    ok: checks.every((check) => check.ok),
    checkedAt: new Date().toISOString(),
    serverUrl: info.serverUrl,
    port: info.port,
    todayUploadCount,
    checks,
  });
}

function checkUpdate(manifestUrl, currentVersionCode) {
  const urls = String(manifestUrl || '').split('|').filter(Boolean);
  const tryUrl = (index) => {
    const url = urls[index];
    if (!url) {
      notify('onNativeUpdateResult', JSON.stringify({ hasUpdate: false, message: '更新检查失败：所有更新地址均不可用' }));
      return;
    }
    https.get(url, (response) => {
      let body = '';
      response.setEncoding('utf8');
      response.on('data', (chunk) => { body += chunk; });
      response.on('end', () => {
        try {
          const json = JSON.parse(body);
          const downloadUrl = json.windowsUrl || json.windows?.url || json.exeUrl || json.apkUrl;
          const nextVersionCode = Number(json.windowsVersionCode || json.versionCode || 0);
          const minimumVersionCode = Number(json.minimumWindowsVersionCode || json.minimumVersionCode || 0);
          const hasUpdate = nextVersionCode > Number(currentVersionCode) && Boolean(downloadUrl);
          notify('onNativeUpdateResult', JSON.stringify({
            ...json,
            versionCode: nextVersionCode,
            minimumVersionCode,
            forceUpdate: Boolean(json.forceWindowsUpdate || (minimumVersionCode && Number(currentVersionCode) < minimumVersionCode)),
            apkUrl: downloadUrl,
            windowsUrl: downloadUrl,
            notes: json.windowsNotes || json.notes,
            hasUpdate,
            message: hasUpdate ? undefined : '当前已是最新版本',
          }));
        } catch {
          tryUrl(index + 1);
        }
      });
    }).on('error', () => tryUrl(index + 1));
  };
  tryUrl(0);
  return true;
}

function downloadAndInstallUpdate(downloadUrl) {
  return openExternalUrl(downloadUrl);
}

function licensedIpc(event, action, handler) {
  const locked = licenseRequiredJson(action);
  if (locked) {
    event.returnValue = locked;
    return;
  }
  event.returnValue = handler();
}

function licensedInvoke(action, handler) {
  const locked = licenseRequiredJson(action);
  if (locked) return Promise.resolve(locked);
  return new Promise((resolve) => {
    setImmediate(() => {
      try {
        resolve(handler());
      } catch (error) {
        resolve(JSON.stringify({ ok: false, message: `${action}失败：${error.message}` }));
      }
    });
  });
}

function deferredInvoke(handler) {
  return new Promise((resolve) => {
    setImmediate(() => {
      try {
        resolve(handler());
      } catch (error) {
        resolve(JSON.stringify({ ok: false, message: `读取数据失败：${error.message}` }));
      }
    });
  });
}

ipcMain.handle('bridge:copyText', (_event, value) => {
  try {
    const text = String(value || '');
    if (!text) {
      return JSON.stringify({ ok: false, message: '没有可复制的内容。' });
    }
    clipboard.writeText(text);
    const normalizeClipboardText = (input) => String(input || '').replace(/\r\n/g, '\n');
    const verified = normalizeClipboardText(clipboard.readText()) === normalizeClipboardText(text);
    return JSON.stringify({ ok: verified, length: text.length, message: verified ? '内容已写入系统剪贴板。' : '剪贴板写入后校验失败，请重试。' });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `复制失败：${error.message}` });
  }
});
